import {factorSkills,isFactoring,factoring,checkFactors} from './factoring.js';
export const skills=['Triangle area','Identifying base & height','Missing dimensions','Grid triangles','Polygon decomposition','Polygon subtraction','Polygon identification','Multi-digit multiplication',...factorSkills];
export const rand=(a,b)=>Math.floor(Math.random()*(b-a+1))+a;
const pick=a=>a[rand(0,a.length-1)];
export const round=n=>Math.round(n*1e8)/1e8;
export function area(v){return Math.abs(v.reduce((s,p,i)=>{let q=v[(i+1)%v.length];return s+p[0]*q[1]-q[0]*p[1]},0))/2}
export function triangle(type,difficulty){let b=rand(4,16),h=rand(3,12);if(difficulty!=='Easy'&&type!=='grid'){b=rand(40,248)/10;h=rand(30,160)/10}if(type==='grid'){b=rand(3,8);h=rand(3,7)}const oblique=type==='grid'&&difficulty==='Hard'&&rand(0,1)===1;if(oblique){b=5*rand(1,2);h=5*rand(1,2)}const x=difficulty==='Easy'?pick([0,b/2]):pick([-b*.4,b*.35,b*1.4]);let v=[[0,0],[b,0],[oblique?0:type==='grid'?Math.round(x):x,h]],foot=[v[2][0],0];let angle=oblique?Math.atan2(4,3):type==='grid'?pick([0,Math.PI/2]):difficulty==='Easy'?0:pick([0,Math.PI/2,-.5]);const rotate=([x,y])=>[x*Math.cos(angle)-y*Math.sin(angle),x*Math.sin(angle)+y*Math.cos(angle)];v=v.map(rotate).map(p=>type==='grid'?p.map(round):p);foot=rotate(foot);let A=round(b*h/2),unit=type==='grid'?'units':pick(['cm','in','ft','yd','m']);let what=type==='missing'?pick(['base','height']):type==='base'?pick(['base','height','area']):'area';let answer=what==='area'?A:what==='base'?b:h;const sq=unit==='units'?'square units':unit+'²';let prompt=type==='missing'?`The triangle has an area of ${A} ${sq} and a ${what==='base'?'height':'base'} of ${what==='base'?h:b} ${unit}. Find its ${what}.`:type==='base'?`Find the ${what==='height'?'perpendicular height corresponding to the marked base':what==='base'?'length of the marked base':'area of this triangle'}.`:type==='grid'?'Each grid square is 1 square unit. What is the area of the triangle?':`A triangle has a base of ${b} ${unit} and a height of ${h} ${unit}. What is its area?`;
let hints=type==='missing'?['Start with A = (b × h) ÷ 2.','Multiply the area by 2 first.',`${what==='height'?'h = (2A) ÷ b':'b = (2A) ÷ h'}. Now substitute the given measurements.`]:['Which measurement is perpendicular to the selected base?','Triangle area is A = (base × height) ÷ 2.',`The base is ${b} ${unit} and its perpendicular height is ${h} ${unit}. ${what==='area'?'Multiply them, then divide by 2.':'Follow the marked measurement.'}`];
let explanation=type==='missing'?`A = (b × h) ÷ 2\n2 × ${A} = ${round(2*A)}\n${what} = ${round(2*A)} ÷ ${what==='base'?h:b} = ${answer} ${unit}`:`Base = ${b} ${unit}; perpendicular height = ${h} ${unit}.\nA = (${b} × ${h}) ÷ 2\nA = ${round(b*h)} ÷ 2 = ${A} ${sq}${what!=='area'?`\nThe requested ${what} is ${answer} ${unit}.`:''}`;
if(oblique){const k=b/5,l=h/5,W=3*k+4*l,H=Math.max(4*k,3*l),gap=Math.abs(4*k-3*l);hints=['For this tilted triangle, use a surrounding rectangle and subtract the outside triangles.','Draw a rectangle through the leftmost, rightmost, highest, and lowest vertices.',`The rectangle is ${W} by ${H}. The lower corner triangles have legs ${4*l} and ${3*l}, and ${3*k} and ${4*k}. The top corner triangle has legs ${W} and ${gap}.`];explanation=`Surrounding rectangle: ${W} × ${H} = ${W*H}\nLower left triangle: ${4*l} × ${3*l} ÷ 2 = ${6*l*l}\nLower right triangle: ${3*k} × ${4*k} ÷ 2 = ${6*k*k}\nTop corner triangle: ${W} × ${gap} ÷ 2 = ${W*gap/2}\nSubtract the three outside pieces: ${W*H} − ${6*l*l} − ${6*k*k} − ${W*gap/2} = ${A} square units.`}
return {type,difficulty,skill:skills[{triangle:0,base:1,missing:2,grid:3}[type]],prompt,correctAnswer:answer,units:what==='area'?sq:unit,hints,explanation,diagramData:{kind:'triangle',vertices:v,foot,b,h,what,unit,grid:type==='grid',oblique,hide:type==='missing'?what:null},misconceptionChecks:[{value:what==='area'?b*h:answer/2,message:what==='area'?'You found base × height. A triangle is half of that rectangle; divide by 2.':'Undo the ÷ 2 in the area formula: double the area before dividing.'},{value:b*Math.hypot(v[2][0]-v[0][0],v[2][1]-v[0][1])/2,message:'Use the perpendicular height, not a slanted side.'}]};}
export function polygon(difficulty,forced){const kind=forced||pick(difficulty==='Easy'?['trapezoid','notch']:['trapezoid','notch','octagon','roof']);let w=rand(7,12),h=rand(6,10),c=rand(1,Math.min(3,Math.floor(h/2)-1)),v,explanation,skill;
if(kind==='octagon'){v=[[c,0],[w-c,0],[w,c],[w,h-c],[w-c,h],[c,h],[0,h-c],[0,c]];explanation=`Surrounding rectangle: ${w} × ${h} = ${w*h}\nEach corner triangle: (${c} × ${c}) ÷ 2 = ${c*c/2}\nSubtract four corners: ${w*h} − ${2*c*c} = ${w*h-2*c*c}`;skill=skills[5]}
if(kind==='notch'){v=[[0,0],[w,0],[w,h-c],[w-c,h-c],[w-c,h],[0,h]];explanation=`Surrounding rectangle: ${w} × ${h} = ${w*h}\nMissing rectangle: ${c} × ${c} = ${c*c}\nSubtract: ${w*h} − ${c*c} = ${w*h-c*c}`;skill=skills[5]}
if(kind==='trapezoid'){v=[[0,0],[w,0],[w-c,h],[c,h]];explanation=`Middle rectangle: ${w-2*c} × ${h} = ${(w-2*c)*h}\nTwo triangles: 2 × (${c} × ${h} ÷ 2) = ${c*h}\nAdd: ${(w-2*c)*h} + ${c*h} = ${(w-c)*h}`;skill=skills[4]}
if(kind==='roof'){v=[[0,0],[w,0],[w,h-c],[w-c,h],[0,h-c]];explanation=`Bottom rectangle: ${w} × ${h-c} = ${w*(h-c)}\nTop triangle: (${w} × ${c}) ÷ 2 = ${w*c/2}\nAdd: ${w*(h-c)} + ${w*c/2} = ${w*(h-c)+w*c/2}`;skill=skills[4]}
return {type:'polygon',difficulty,skill,prompt:'Find the area of the shaded polygon. Each grid square is 1 square unit.',correctAnswer:area(v),units:'square units',diagramData:{kind:'polygon',vertices:v,w,h,c,shape:kind,grid:true},hints:[skill===skills[5]?'Imagine a rectangle around the entire shape.':'Can you divide the polygon into a rectangle and triangles?','Look at the dashed construction lines.','Count the lengths on the grid. The surrounding rectangle is '+w+' units by '+h+' units.',skill===skills[5]?'Multiply the rectangle dimensions, then subtract the areas of the missing pieces.':'Use length × width for the rectangle and base × height ÷ 2 for each triangle. Add the pieces.'],explanation:explanation+' square units.',misconceptionChecks:[{value:w*h,message:'That is the surrounding rectangle. Account for the missing pieces.'}]};}
export const shapes=[{id:'pentagon',name:'Pentagon',path:'M15 55 L10 25 L40 8 L70 25 L65 55 Z',polygon:true},{id:'star',name:'Star',path:'M40 5 L49 25 L73 26 L55 40 L61 64 L40 51 L19 64 L25 40 L7 26 L31 25 Z',polygon:true},{id:'open',name:'Open figure',path:'M12 55 L12 15 L65 15 L65 55',polygon:false},{id:'heart',name:'Heart',path:'M40 61 C-15 28 15 -2 40 20 C65 -2 95 28 40 61 Z',polygon:false},{id:'curve',name:'Curved edge',path:'M15 55 L15 15 Q70 -5 70 55 Z',polygon:false},{id:'cube',name:'3D cube drawing',path:'M12 25 L40 8 L69 25 L69 53 L40 68 L12 52 Z M12 25 L40 40 L69 25 M40 40 L40 68',polygon:false}];
export function identification(difficulty){return {type:'identification',difficulty,skill:skills[6],prompt:'Select all the polygons.',options:[...shapes].sort(()=>Math.random()-.5),correctAnswer:['pentagon','star'],units:'',hints:['A polygon is a closed 2D figure.','Every edge must be a straight line segment.','A concave shape can be a polygon. Open figures, curves, and 3D drawings do not qualify.'],explanation:'The pentagon and star are closed 2D figures made entirely of straight line segments. The others are open, curved, or a drawing of a 3D object.'};}
export function multiplication(difficulty){const a=difficulty==='Easy'?rand(100,999):pick([rand(100,999),rand(1000,9999)]),b=a>999||difficulty==='Easy'?rand(12,99):rand(101,999),partials=String(b).split('').reverse().map((n,i)=>a*Number(n)*10**i);return {type:'multiplication',difficulty,skill:skills[7],prompt:'Find the product. Use partial products if they help.',correctAnswer:a*b,units:'',a,b,partials,hints:['Multiply by each digit of the second number.','Remember the place value: tens represent groups of 10; hundreds represent groups of 100.','Add the partial products to find the final product.'],explanation:partials.map((n,i)=>`${a} × ${Number(String(b).split('').reverse()[i])*10**i} = ${n.toLocaleString('en-US')}`).join('\n')+`\n${partials.join(' + ')} = ${(a*b).toLocaleString('en-US')}`};}
export function reasoning(difficulty){let p=triangle('triangle',difficulty),correct=!!rand(0,1),claim=correct?p.correctAnswer:p.correctAnswer*2;p.type='reasoning';p.prompt=`Shawn says this triangle has an area of ${round(claim)} ${p.units}. Is Shawn correct? Choose a reason too.`;p.numericAnswer=p.correctAnswer;p.correctAnswer={yes:correct,reason:correct?'half':'double'};p.reasons=[{id:'half',text:'Yes. A triangle is half of base × perpendicular height.'},{id:'double',text:'No. Shawn used base × height without dividing by 2.'},{id:'slant',text:'Use a slanted side instead of the perpendicular height.'},{id:'linear',text:'Area should be written in linear units.'},{id:'multiply',text:'Multiply the stated area by the base.'}];return p;}
export function generate(mode,difficulty){let type=mode==='mixed'?pick(['triangle','base','missing','grid','polygon','identification','reasoning','multiplication']):mode==='challenge'?pick(['triangle','base','missing','grid','polygon','identification','reasoning']):mode==='polygon'?pick(['polygon','polygon','polygon','identification']):mode;let p=isFactoring(type)?factoring(type,difficulty):type==='polygon'?polygon(difficulty):type==='identification'?identification(difficulty):type==='multiplication'?multiplication(difficulty):type==='reasoning'?reasoning(difficulty):triangle(type,difficulty);validateProblem(p);return p}
export function validateProblem(p){const d=p.diagramData;if(d?.kind==='triangle'){if(Math.abs(area(d.vertices)-d.b*d.h/2)>1e-6)throw Error('Triangle area mismatch');let [a,b,c]=d.vertices,u=[b[0]-a[0],b[1]-a[1]],v=[c[0]-d.foot[0],c[1]-d.foot[1]];if(Math.abs(u[0]*v[0]+u[1]*v[1])>1e-6)throw Error('Altitude not perpendicular')}if(d?.kind==='polygon'&&Math.abs(area(d.vertices)-p.correctAnswer)>1e-6)throw Error('Polygon mismatch');if(typeof p.correctAnswer==='number'&&(!Number.isFinite(p.correctAnswer)||p.correctAnswer<=0))throw Error('Invalid answer');return true}
export function checkAnswer(p,raw){if(p.type==='factors'||p.type==='common')return checkFactors(p,raw);if(p.type==='identification'){return {correct:Array.isArray(raw)&&[...raw].sort().join()===p.correctAnswer.slice().sort().join(),message:'Check that each selected figure is closed, flat, and has only straight edges.'}}if(p.type==='reasoning')return {correct:raw.yes===p.correctAnswer.yes&&raw.reason===p.correctAnswer.reason,message:'Recheck both your Yes / No choice and your reason. Use the perpendicular height and remember the factor of one-half.'};let match=String(raw).trim().replace(/,/g,'').match(/^([+-]?(?:\d+(?:\.\d*)?|\.\d+))\s*(.*?)$/);if(!match)return {correct:false,invalid:true,message:'Enter a number, with optional units, such as 24.5.'};let n=Number(match[1]),u=match[2].toLowerCase().replace(/\s+/g,' ');if(u){const square=p.units.includes('²')||p.units==='square units',linear=p.units.replace('²','').replace('square ','');const normalized=u.replace(/\^2|²/g,'2');let valid=square?[linear+'2','square '+linear,'sq '+linear]:[linear];if(!valid.includes(normalized))return {correct:false,message:square?'Area is measured in square units. Use '+p.units+'.':'Use '+(p.units||'a number without units')+' for this answer.'}}
if(Math.abs(n-p.correctAnswer)<1e-7)return {correct:true,message:'Correct!'};const misconception=p.misconceptionChecks?.find(c=>Math.abs(c.value-n)<1e-6);return {correct:false,message:misconception?.message||(p.type==='gcf'?'List the factors of both numbers, then choose the largest factor they share.':'Not quite yet. Check your measurements and calculation, then try again.')}}


